@keyframes deepSpaceNebulaPulse {
  0%, 100% {
    background-position: 0% 0%, 100% 100%, 0 0;
    filter: brightness(1);
  }
  50% {
    background-position: 100% 50%, 0% 50%, 0 0;
    filter: brightness(1.25);
  }
}
[data-workspace-area="conversation"] {
  background-color: #060813 !important;
  background-image: 
    radial-gradient(circle at 30% 40%, rgba(99, 102, 241, 0.28) 0%, transparent 50%),
    radial-gradient(circle at 75% 65%, rgba(14, 165, 233, 0.25) 0%, transparent 50%),
